            if ( ! empty( $res['carrier'] ) && $res['carrier'] === 'venipak' ) {
                $has_venipak_only = true;
            }
            if ( ! empty( $res['courier_only'] ) ) {
                $has_courier_only = true;
            }
            if ( get_post_meta( $pid, '_fulfillment_courier_only', true ) === 'yes' ) {
                $has_courier_only = true;
            }
